CREATE FUNCTION public.pilot_pending_offer_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pilot boolean;c jsonb;BEGIN SELECT pilot_wave INTO pilot FROM public.trip_distributions WHERE id=NEW.distribution_id;SELECT pilot_config INTO c FROM public.trip_network_settings WHERE id=true;IF pilot AND coalesce((c->>'emergencyStop')::boolean,true) AND NEW.status NOT IN ('closed','expired','declined') AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.amount_cents IS DISTINCT FROM OLD.amount_cents OR NEW.expires_at IS DISTINCT FROM OLD.expires_at) THEN RAISE EXCEPTION 'Pilot stopped; pending offer frozen for review';END IF;RETURN NEW;END $$;
CREATE TRIGGER pilot_pending_freeze BEFORE UPDATE ON public.provider_trip_offers FOR EACH ROW EXECUTE FUNCTION public.pilot_pending_offer_guard();
CREATE FUNCTION public.pilot_settings_insert_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce((NEW.pilot_config->>'enabled')::boolean,false) OR coalesce((NEW.pilot_config->>'inApp')::boolean,false) OR jsonb_array_length(coalesce(NEW.pilot_config->'senders','[]'::jsonb))>0 OR jsonb_array_length(coalesce(NEW.pilot_config->'receivers','[]'::jsonb))>0 THEN RAISE EXCEPTION 'Initial pilot must be off with no selected workspaces';END IF;RETURN NEW;END $$;
CREATE TRIGGER pilot_default_off_insert BEFORE INSERT ON public.trip_network_settings FOR EACH ROW EXECUTE FUNCTION public.pilot_settings_insert_guard();